from __future__ import annotations


HTML = r"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PhonoWeave — Live Calibration</title>
<style>
:root{--chrome:#ecece8;--line:#9fa19d;--ink:#171816;--muted:#60635e;--sel:#1d4f91;--ok:#24653f;--danger:#8d2f2f;--mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:#f4f4f1;color:var(--ink);font:13px/1.35 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;overflow:hidden}.app{height:100%;display:grid;grid-template-rows:32px 42px 1fr 25px}.menubar,.toolbar,.statusbar{background:var(--chrome)}.menubar{display:flex;align-items:center;border-bottom:1px solid var(--line);padding:0 8px;gap:18px;font-size:12px}.brand{font-weight:700}.spacer{flex:1}.back{color:inherit;text-decoration:none}.lang button,.toolbtn{font:inherit;border:1px solid #7f817c;background:#fff;height:27px;padding:3px 9px;cursor:pointer}.lang button.active{background:#2c2d2a;color:#fff}.toolbar{display:flex;align-items:center;gap:7px;padding:6px 8px;border-bottom:1px solid var(--line)}.toolbtn.primary{background:#30322f;color:#fff}.toolbtn:disabled{opacity:.45}.session{margin-left:auto;font:10px var(--mono);color:var(--muted);max-width:42vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.workspace{min-height:0;display:grid;grid-template-columns:235px minmax(420px,1fr) 330px}.pane{min-width:0;min-height:0;border-right:1px solid var(--line);display:grid;grid-template-rows:27px 1fr}.pane:last-child{border-right:0}.panehead{display:flex;align-items:center;padding:0 8px;background:#dadbd7;border-bottom:1px solid var(--line);font-size:10px;text-transform:uppercase;letter-spacing:.8px;font-weight:700}.panehead span:last-child{margin-left:auto;font-family:var(--mono);font-weight:400}.list{overflow:auto;background:#e9eae6}.item{display:grid;grid-template-columns:34px 1fr 24px;padding:5px 8px;border-bottom:1px solid #d2d3cf;cursor:pointer}.item:hover{background:#dddeda}.item.selected{background:var(--sel);color:#fff}.item.done .state{color:var(--ok)}.base{font:bold 12px var(--mono)}.ctx{font-size:10px;color:#666}.item.selected .ctx{color:#e0e8f4}.state{text-align:right;font:11px var(--mono)}.stage{display:grid;grid-template-rows:1fr auto;background:#fff}.promptarea{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:18px}.promptmeta{font:11px var(--mono);color:var(--muted);margin-bottom:18px}.pattern{font:700 38px/1.3 var(--mono);letter-spacing:1px;text-align:center}.token{padding:3px 5px;border-bottom:3px solid transparent}.token.hot{background:#e6edf7;border-bottom-color:var(--sel)}.beat{margin-top:20px;font:12px var(--mono);color:var(--muted)}.progressbar{height:4px;background:#dedfdb;width:min(560px,80%);margin-top:8px}.progress{height:100%;background:#555;width:0}.controls{display:flex;align-items:center;justify-content:center;gap:7px;padding:10px;border-top:1px solid var(--line);background:#ecece8}.controls button{font:inherit;border:1px solid #7f817c;background:#fff;height:29px;padding:4px 12px}.controls .record{background:#30322f;color:#fff}.recording{color:var(--danger);font:11px var(--mono);min-width:90px}.monitor{overflow:auto;background:#f3f3ef;padding:10px;display:grid;grid-template-rows:auto 120px auto 120px auto auto;gap:8px}.label{font:10px var(--mono);text-transform:uppercase;letter-spacing:.7px;color:var(--muted)}canvas{width:100%;height:120px;background:#fff;border:1px solid var(--line)}audio{width:100%;height:34px}.meta{font:11px var(--mono);color:#555;line-height:1.5}.statusbar{display:flex;align-items:center;border-top:1px solid var(--line);padding:0 8px;font:10px var(--mono);color:#464844}.statusbar .spacer{flex:1}.error{color:var(--danger)}</style>
</head><body><div class="app">
<div class="menubar"><span class="brand">PHONOWEAVE</span><a class="back" href="/">Workbench</a><span>LIVE CALIBRATION</span><span class="spacer"></span><div class="lang"><button id="zh">中文</button><button id="en">EN</button></div></div>
<div class="toolbar"><button class="toolbtn primary" id="start"></button><button class="toolbtn" id="mic"></button><button class="toolbtn" id="record" disabled></button><button class="toolbtn" id="retry" disabled></button><button class="toolbtn" id="play" disabled></button><button class="toolbtn" id="prev" disabled></button><button class="toolbtn" id="next" disabled></button><span class="session" id="session">—</span></div>
<div class="workspace"><section class="pane"><div class="panehead"><span id="prompts-title"></span><span id="count">0/0</span></div><div class="list" id="list"></div></section><section class="pane"><div class="panehead"><span id="elicitation-title"></span><span id="index-label">—</span></div><div class="stage"><div class="promptarea"><div class="promptmeta" id="meta"></div><div class="pattern" id="pattern">—</div><div class="beat" id="beat"></div><div class="progressbar"><div class="progress" id="progress"></div></div></div><div class="controls"><button class="record" id="record2" disabled></button><span class="recording" id="recording"></span></div></div></section><section class="pane"><div class="panehead"><span id="monitor-title"></span></div><div class="monitor"><div class="label" id="input-label"></div><canvas id="live"></canvas><div class="label" id="take-label"></div><canvas id="take"></canvas><audio id="audio" controls></audio><div class="meta" id="take-meta">—</div></div></section></div>
<div class="statusbar"><span id="status"></span><span class="spacer"></span><span id="saved"></span></div></div>
<script>
const $=id=>document.getElementById(id);let lang=localStorage.getItem('phonoweave.language')||'zh';let protocol=null,session=null,index=0,stream=null,audioCtx=null,source=null,processor=null,analyser=null,chunks=[],sampleRate=0,busy=false,done=new Set(),takes=new Map();
const T={zh:{start:'新建会话',mic:'启用麦克风',record:'录制',retry:'重录',play:'回放',prev:'上一项',next:'下一项',prompts:'提示词',elicitation:'录音',monitor:'录音监视',input:'实时输入波形',take:'当前录音',ready:'新建会话并启用麦克风。',starting:'正在新建会话…',micReady:'麦克风已启用。',micFail:'无法使用麦克风：',recording:'● REC',saved:'已保存',complete:'已录完全部提示词。'},en:{start:'New session',mic:'Enable microphone',record:'Record',retry:'Redo',play:'Play',prev:'Previous',next:'Next',prompts:'Prompts',elicitation:'Recording',monitor:'Monitor',input:'Live input waveform',take:'Current take',ready:'Create a session and enable the microphone.',starting:'Creating session…',micReady:'Microphone enabled.',micFail:'Could not use microphone: ',recording:'● REC',saved:'Saved',complete:'All prompts recorded.'}};
function t(k){return T[lang][k]}function setStatus(s,e=false){$('status').textContent=s;$('status').classList.toggle('error',e)}function currentPrompt(){return protocol?.prompts[index]||null}
function apply(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';localStorage.setItem('phonoweave.language',lang);$('zh').classList.toggle('active',lang==='zh');$('en').classList.toggle('active',lang==='en');[['start','start'],['mic','mic'],['record','record'],['record2','record'],['retry','retry'],['play','play'],['prev','prev'],['next','next'],['prompts-title','prompts'],['elicitation-title','elicitation'],['monitor-title','monitor'],['input-label','input'],['take-label','take']].forEach(([id,k])=>$(id).textContent=t(k));if(!session)setStatus(t('ready'));render()}
function render(){if(!protocol){$('list').innerHTML='';return}let h='';protocol.prompts.forEach((p,i)=>{h+=`<div class="item ${i===index?'selected':''} ${done.has(i)?'done':''}" data-i="${i}"><span class="base">${p.base_unit}</span><span><div>${p.spoken_pattern}</div><div class="ctx">${p.context_family}</div></span><span class="state">${done.has(i)?'✓':''}</span></div>`});$('list').innerHTML=h;document.querySelectorAll('.item').forEach(x=>x.onclick=()=>{if(!busy){index=Number(x.dataset.i);render();showTake()}});$('count').textContent=`${done.size}/${protocol.prompts.length}`;const p=currentPrompt();if(!p)return;$('index-label').textContent=`${String(index+1).padStart(2,'0')} / ${protocol.prompts.length}`;$('meta').textContent=`${p.base_unit} · ${p.context_family} · ${p.role_scope}`;$('pattern').innerHTML=p.tokens.map((x,i)=>`<span class="token" data-token="${i}">${x}</span>`).join(' ');$('record').disabled=!session||!stream||busy;$('record2').disabled=$('record').disabled;$('retry').disabled=!done.has(index)||busy;$('play').disabled=!takes.has(index)||busy;$('prev').disabled=busy||index<=0;$('next').disabled=busy||index>=protocol.prompts.length-1}
async function startSession(){setStatus(t('starting'));const r=await fetch('/api/calibration/start',{method:'POST'}),d=await r.json();if(!r.ok){setStatus(d.error||'error',true);return}protocol=d.protocol;session=d.session_id;index=0;done.clear();takes.clear();$('session').textContent=`${session} · ${d.session_dir}`;$('audio').removeAttribute('src');clearCanvas($('take'));$('take-meta').textContent='—';setStatus(t('ready'));render()}
async function enableMic(){try{stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:false,noiseSuppression:false,autoGainControl:false}});setupMonitor();setStatus(t('micReady'));render()}catch(e){setStatus(t('micFail')+e.message,true)}}
function setupMonitor(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();source=audioCtx.createMediaStreamSource(stream);analyser=audioCtx.createAnalyser();analyser.fftSize=2048;source.connect(analyser);drawLive()}
function resizeCanvas(c){const d=window.devicePixelRatio||1,w=Math.max(1,Math.floor(c.clientWidth*d)),h=Math.max(1,Math.floor(c.clientHeight*d));if(c.width!==w||c.height!==h){c.width=w;c.height=h}}
function clearCanvas(c){resizeCanvas(c);c.getContext('2d').clearRect(0,0,c.width,c.height)}
function drawLive(){const c=$('live'),g=c.getContext('2d');resizeCanvas(c);const a=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(a);g.clearRect(0,0,c.width,c.height);g.beginPath();for(let i=0;i<a.length;i++){const x=i/(a.length-1)*c.width,y=(a[i]/255)*c.height;if(i===0)g.moveTo(x,y);else g.lineTo(x,y)}g.stroke();requestAnimationFrame(drawLive)}
function beginCapture(){sampleRate=audioCtx.sampleRate;processor=audioCtx.createScriptProcessor(4096,1,1);chunks=[];processor.onaudioprocess=e=>chunks.push(new Float32Array(e.inputBuffer.getChannelData(0)));source.connect(processor);processor.connect(audioCtx.destination)}
function endCapture(){processor.disconnect();source.disconnect(processor);let n=chunks.reduce((a,x)=>a+x.length,0),samples=new Float32Array(n),o=0;for(const x of chunks){samples.set(x,o);o+=x.length}return samples}
function encodeWav(samples,sr){const b=new ArrayBuffer(44+samples.length*2),v=new DataView(b);function s(o,x){for(let i=0;i<x.length;i++)v.setUint8(o+i,x.charCodeAt(i))}s(0,'RIFF');v.setUint32(4,36+samples.length*2,true);s(8,'WAVE');s(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);s(36,'data');v.setUint32(40,samples.length*2,true);let o=44;for(let i=0;i<samples.length;i++,o+=2){let x=Math.max(-1,Math.min(1,samples[i]));v.setInt16(o,x<0?x*32768:x*32767,true)}return b}
function drawTake(samples){const c=$('take'),g=c.getContext('2d');resizeCanvas(c);g.clearRect(0,0,c.width,c.height);g.beginPath();const step=Math.max(1,Math.floor(samples.length/c.width));for(let x=0;x<c.width;x++){let m=0;for(let j=0;j<step;j++){const i=x*step+j;if(i<samples.length)m=Math.max(m,Math.abs(samples[i]))}const y1=c.height/2-m*c.height*.46,y2=c.height/2+m*c.height*.46;g.moveTo(x,y1);g.lineTo(x,y2)}g.stroke()}
function beep(accent=false){const a=new (window.AudioContext||window.webkitAudioContext)(),osc=a.createOscillator(),g=a.createGain();osc.frequency.value=accent?1000:700;g.gain.value=.04;osc.connect(g);g.connect(a.destination);osc.start();osc.stop(a.currentTime+.06);osc.onended=()=>a.close()}function sleep(ms){return new Promise(r=>setTimeout(r,ms))}
async function recordCurrent(){if(busy||!session||!stream)return;busy=true;render();$('recording').textContent=t('recording');const p=currentPrompt(),beatMs=60000/72;beginCapture();await sleep(250);beep(true);await sleep(beatMs);for(let ti=0;ti<p.tokens.length;ti++){document.querySelectorAll('.token').forEach((x,i)=>x.classList.toggle('hot',i===ti));beep(ti===0);$('beat').textContent=`${ti+1}/${p.tokens.length}`;$('progress').style.width=`${(ti+1)/p.tokens.length*100}%`;await sleep(beatMs)}document.querySelectorAll('.token').forEach(x=>x.classList.remove('hot'));beep(true);await sleep(beatMs);const samples=endCapture(),wav=encodeWav(samples,sampleRate),blob=new Blob([wav],{type:'audio/wav'}),url=URL.createObjectURL(blob);const r=await fetch(`/api/calibration/recording?index=${index}&sample_rate=${sampleRate}`,{method:'POST',headers:{'Content-Type':'audio/wav'},body:wav}),d=await r.json();if(r.ok){const old=takes.get(index);if(old?.url)URL.revokeObjectURL(old.url);takes.set(index,{samples,url,path:d.saved});done.add(index);$('saved').textContent=`${t('saved')}: ${d.saved}`;drawTake(samples);$('audio').src=url;$('take-meta').textContent=`${p.syllable} · ${p.context_family} · ${(samples.length/sampleRate).toFixed(2)} s`;if(index<protocol.prompts.length-1)index++;else setStatus(t('complete'))}else setStatus(d.error||'save failed',true);$('recording').textContent='';$('beat').textContent='';$('progress').style.width='0%';busy=false;render();showTake()}
function showTake(){const take=takes.get(index),p=currentPrompt();if(!take){$('audio').removeAttribute('src');clearCanvas($('take'));$('take-meta').textContent='—';return}$('audio').src=take.url;drawTake(take.samples);$('take-meta').textContent=`${p.syllable} · ${p.context_family} · ${(take.samples.length/sampleRate).toFixed(2)} s`}
$('start').onclick=startSession;$('mic').onclick=enableMic;$('record').onclick=recordCurrent;$('record2').onclick=recordCurrent;$('retry').onclick=recordCurrent;$('play').onclick=()=>{if($('audio').src)$('audio').play()};$('prev').onclick=()=>{if(index>0){index--;render();showTake()}};$('next').onclick=()=>{if(protocol&&index<protocol.prompts.length-1){index++;render();showTake()}};$('zh').onclick=()=>{lang='zh';apply()};$('en').onclick=()=>{lang='en';apply()};apply();
</script></body></html>
"""
